static void ambient(void *ctx,AudioQueueRef aq,AudioQueueBufferRef b){float *o=b->mAudioData;for(int i=0;i<4096;i++,sampleIndex++){double t=sampleIndex/44100.,n=rnd((unsigned)sampleIndex);noiseLP+=(n-noiseLP)*.012;double breath=.65+.22*sin(t*.13)+.13*sin(t*.071+.7);double tone=sin(6.2831853*55*t+.18*sin(t*.07))*.045+sin(6.2831853*82.4069*t+.2*sin(t*.055+1.))*.031+sin(6.2831853*110*t+.13*sin(t*.09))*.024+sin(6.2831853*164.8138*t+.12*sin(t*.07+1.))*.016+sin(6.2831853*220*t+.17*sin(t*.041+2.))*.009;double s=(noiseLP*.025*breath+tone)*fmin(1.,t/4.)*fmax(0.,fmin(1.,(96.-t)/5.));o[2*i]=s;o[2*i+1]=s*.94;}b->mAudioDataByteSize=32768;AudioQueueEnqueueBuffer(aq,b,0,0);}
static void render(id<MTLTexture> texture,float t,id<CAMetalDrawable> drawable){MTLRenderPassDescriptor *pass=[MTLRenderPassDescriptor renderPassDescriptor];pass.colorAttachments[0].texture=texture;pass.colorAttachments[0].loadAction=MTLLoadActionDontCare;pass.colorAttachments[0].storeAction=MTLStoreActionStore;id<MTLCommandBuffer> cb=[queue commandBuffer];id<MTLRenderCommandEncoder> enc=[cb renderCommandEncoderWithDescriptor:pass];float u[4]={texture.width,texture.height,t,0};[enc setRenderPipelineState:pipeline];[enc setFragmentBytes:u length:sizeof(u) atIndex:0];[enc drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:3];[enc endEncoding];if(drawable)[cb presentDrawable:drawable];[cb commit];[cb waitUntilCompleted];}
@interface Demo:NSObject<NSApplicationDelegate>
@property(strong) NSWindow *window;
@end
@implementation Demo
-(BOOL)applicationShouldTerminateAfterLastWindowClosed:(NSApplication*)app{return YES;}
-(void)tick:(NSTimer*)timer{float t=NSProcessInfo.processInfo.systemUptime-start;if(t>=96){[NSApp terminate:nil];return;}@autoreleasepool{NSSize s=self.window.contentView.bounds.size;CGFloat scale=self.window.backingScaleFactor;layer.frame=self.window.contentView.bounds;float factor=fmin(1.,1280./(s.width*scale));layer.drawableSize=CGSizeMake(s.width*scale*factor,s.height*scale*factor);id<CAMetalDrawable> d=[layer nextDrawable];if(d)render(d.texture,t,d);}}
-(void)applicationDidFinishLaunching:(NSNotification*)n{self.window=[[NSWindow alloc]initWithContentRect:NSMakeRect(0,0,1152,648) styleMask:NSWindowStyleMaskTitled|NSWindowStyleMaskClosable|NSWindowStyleMaskResizable backing:NSBackingStoreBuffered defer:NO];self.window.title=@"Dem2 / 64K — Esc: quit · F: fullscreen";layer=[CAMetalLayer layer];layer.device=gpu;layer.pixelFormat=MTLPixelFormatBGRA8Unorm;self.window.contentView.wantsLayer=YES;self.window.contentView.layer=layer;[self.window center];[self.window makeKeyAndOrderFront:nil];[NSApp activateIgnoringOtherApps:YES];[NSEvent addLocalMonitorForEventsMatchingMask:NSEventMaskKeyDown handler:^NSEvent*(NSEvent *e){if(e.keyCode==53||([e.charactersIgnoringModifiers isEqualToString:@"q"]&&(e.modifierFlags&NSEventModifierFlagCommand))){[NSApp terminate:nil];return nil;}if(e.keyCode==3||[e.charactersIgnoringModifiers.lowercaseString isEqualToString:@"f"]||[e.charactersIgnoringModifiers.lowercaseString isEqualToString:@"а"]){[self.window toggleFullScreen:nil];return nil;}return e;}];AudioStreamBasicDescription f={44100,kAudioFormatLinearPCM,kAudioFormatFlagIsFloat|kAudioFormatFlagIsPacked,8,1,8,2,32,0};if(AudioQueueNewOutput(&f,ambient,0,0,0,0,&audio)==0){for(int i=0;i<3;i++){AudioQueueBufferRef b;AudioQueueAllocateBuffer(audio,32768,&b);ambient(0,audio,b);}AudioQueueStart(audio,0);}start=NSProcessInfo.processInfo.systemUptime;[NSTimer scheduledTimerWithTimeInterval:1./60 target:self selector:@selector(tick:) userInfo:nil repeats:YES];}
-(void)applicationWillTerminate:(NSNotification*)n{if(audio){AudioQueueStop(audio,true);AudioQueueDispose(audio,true);}}
