int main(int argc,char **argv){@autoreleasepool{gpu=MTLCreateSystemDefaultDevice();if(!gpu){fprintf(stderr,"Metal device unavailable\n");return 1;}NSError *err=nil;id<MTLLibrary> lib=[gpu newLibraryWithSource:@SHADER options:nil error:&err];MTLRenderPipelineDescriptor *desc=[MTLRenderPipelineDescriptor new];desc.vertexFunction=[lib newFunctionWithName:@"vert"];desc.fragmentFunction=[lib newFunctionWithName:@"frag"];desc.colorAttachments[0].pixelFormat=MTLPixelFormatBGRA8Unorm;pipeline=[gpu newRenderPipelineStateWithDescriptor:desc error:&err];if(!pipeline){fprintf(stderr,"%s\n",err.description.UTF8String);return 2;}queue=[gpu newCommandQueue];if(argc==4&&!strcmp(argv[1],"--capture")){MTLTextureDescriptor *td=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatBGRA8Unorm width:1280 height:720 mipmapped:NO];td.usage=MTLTextureUsageRenderTarget;td.storageMode=MTLStorageModeShared;id<MTLTexture> tex=[gpu newTextureWithDescriptor:td];render(tex,atof(argv[2]),nil);unsigned char *pixels=malloc(1280*720*4);[tex getBytes:pixels bytesPerRow:1280*4 fromRegion:MTLRegionMake2D(0,0,1280,720) mipmapLevel:0];NSBitmapImageRep *rep=[[NSBitmapImageRep alloc]initWithBitmapDataPlanes:NULL pixelsWide:1280 pixelsHigh:720 bitsPerSample:8 samplesPerPixel:4 hasAlpha:YES isPlanar:NO colorSpaceName:NSDeviceRGBColorSpace bytesPerRow:5120 bitsPerPixel:32];unsigned char *dst=rep.bitmapData;for(int i=0;i<1280*720;i++){dst[i*4]=pixels[i*4+2];dst[i*4+1]=pixels[i*4+1];dst[i*4+2]=pixels[i*4];dst[i*4+3]=255;}[[rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}]writeToFile:@(argv[3]) atomically:YES];free(pixels);return 0;}[NSApplication sharedApplication];[NSApp setActivationPolicy:NSApplicationActivationPolicyRegular];Demo *demo=[Demo new];NSApp.delegate=demo;[NSApp run];}return 0;}
